export function indentEdit(text: string, from: number, to: number, out: boolean): FormatEdit | null {
  function sameListContainer(text: string, positions: number[]) {
    // Callers supply ordered UTF-16 offsets. Count normalized lines in one pass.
    const breaks = text.matchAll(/\r\n?|\n/g);
    let next = breaks.next(), lineNumber = 0;
    const lines = positions.map(position => {
      while (!next.done && next.value.index! + next.value[0].length <= position) {
        lineNumber++; next = breaks.next();
      }
      return lineNumber;
    });
    const containers = new Map<number, object | null>();
    const stack: object[] = [];
    for (const token of new MarkdownIt({ html: false }).parse(text, {})) {
      if (token.type === 'list_item_open') {
        const line = token.map?.[0];
        // The raw line scanner describes the first marker on a line.
        if (line !== undefined && !containers.has(line)) containers.set(line, stack.at(-1) ?? null);
        stack.push(token);
      } else if (token.type === 'list_item_close') stack.pop();
    }
    return lines.every(line => containers.has(line) && containers.get(line) === containers.get(lines[0]!));
  }
  const { start, end } = lineSpan(text, from, to);
  const lines = text.slice(start, end).split('\n');
  if (!lines.some((line) => line.trim()) || !lines.every((line) => !line.trim() || LIST_LINE.test(line))) return null;
  const first = lines.findIndex((line) => line.trim());
  const before = text.slice(0, start).trimEnd();
  const aboveStart = before.lastIndexOf('\n') + 1;
  const above = before.slice(aboveStart);
  const opening = /^([ \t]*)([-*+]|\d{1,9}[.)])([ \t]+|$)/.exec(above);
  const level = /^[ \t]*/.exec(lines[first]!)![0];
  let spaces = INDENT.length;
  let rangeIndent: string | undefined;
  if (!out && opening) {
    const column = (source: string, at = 0) => {
      for (const character of source) at += character === '\t' ? 4 - at % 4 : 1;
      return at;
    };
    const markerEnd = column(opening[1] + opening[2]);
    const gap = column(opening[3]!, markerEnd) - markerEnd;
    // CommonMark uses one column when larger padding introduces a code child.
    const content = markerEnd + (gap && gap <= 4 ? gap : 1);
    // Prefixing spaces can change a following tab's width; measure that prefix.
    let at = start;
    const selected = lines.flatMap(line => {
      const row = line.trim() ? [{ at, indent: /^[ \t]*/.exec(line)![0] }] : [];
      at += line.length + 1;
      return row;
    });
    if (from !== to && selected.length > 1 && selected.some(row => column(row.indent, spaces) < content)
      && sameListContainer(text, [aboveStart, ...selected.map(row => row.at)])) {
      // A common prefix can move tab-indented peers to different columns. Align
      // selected peers when four spaces cannot put every item under the parent.
      rangeIndent = ' '.repeat(selected.reduce((size, row) => Math.max(size, column(row.indent) + INDENT.length), content));
    } else if (column(level, spaces) < content
      && (column(opening[1]!) === column(level) || sameListContainer(text, [aboveStart, selected[0]!.at]))) {
      while (column(level, spaces) < content) spaces++;
    }
  }
  const indent = ' '.repeat(spaces);
  const moved = lines.map(line => {
    if (!line.trim()) return line;
    if (out) return line.replace(/^(?: {1,4}|\t)/, '');
    return rangeIndent === undefined ? indent + line : line.replace(/^[ \t]*/, rangeIndent);
  });
  // A numbered item that opens a sublist must be number 1: markdown reads any other
  // number straight after its parent's text as more of that text, not as a list.
  if (!out) {
    const depth = /^[ \t]*/.exec(moved[first]!)![0];
    // With no list above to go under, four spaces would make the line a code block.
    if (!LIST_LINE.test(above) && !/^[ \t]+\S/.test(above)) return null;
    const continues = lines.slice(0, first).length === 0 && above.startsWith(depth) && /^\d{1,9}[.)]/.test(above.slice(depth.length));
    if (!continues) moved[first] = moved[first]!.replace(/^([ \t]*)\d{1,9}([.)])/, '$11$2');
  }
  const insert = moved.join('\n');
  if (insert === lines.join('\n')) return null;
  if (from !== to) return { from: start, to: end, insert, start, end: start + insert.length };
  // A caret stays on its character; one inside the removed indent goes to the line's start.
  const caret = Math.max(start, from + moved[0]!.length - lines[0]!.length);
  return { from: start, to: end, insert, start: caret, end: caret };
}
